import{_ as a,o,c as i,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_2.md"}'),n={name:"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_2.md"};function r(s,e,l,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-redes-trayecto-ii" tabindex="-1">Materia: Redes (Trayecto II) <a class="header-anchor" href="#materia-redes-trayecto-ii" aria-label="Permalink to &quot;Materia: Redes (Trayecto II)&quot;">​</a></h2><h3 id="eje-tematico-direccionamiento-enrutamiento-y-subnetting" tabindex="-1">Eje Temático: Direccionamiento, Enrutamiento y Subnetting <a class="header-anchor" href="#eje-tematico-direccionamiento-enrutamiento-y-subnetting" aria-label="Permalink to &quot;Eje Temático: Direccionamiento, Enrutamiento y Subnetting&quot;">​</a></h3><hr><h2 id="🧭-introduccion-el-sistema-postal-global" tabindex="-1">🧭 Introducción: El Sistema Postal Global <a class="header-anchor" href="#🧭-introduccion-el-sistema-postal-global" aria-label="Permalink to &quot;🧭 Introducción: El Sistema Postal Global&quot;">​</a></h2><p>El Switch sabe cómo mover datos dentro de un edificio porque usa Direcciones MAC (que vienen grabadas de fábrica en el hardware). Pero las Direcciones MAC no tienen un orden geográfico. Es como intentar encontrar a &quot;Juan Pérez&quot; en el mundo sabiendo solo su nombre, sin saber en qué país o ciudad vive.</p><p>Para que internet funcione, la Capa 3 del modelo OSI utiliza <strong>Direcciones IP lógicas</strong>. Una IP no te dice <em>quién</em> es el equipo, te dice <em>dónde está</em>. Funciona exactamente igual que tu dirección postal: <code>País -&gt; Estado -&gt; Ciudad -&gt; Calle -&gt; Casa</code>. El proceso matemático para crear estas calles y casas lógicas se llama <strong>Subnetting (Subredes)</strong>.</p><hr><h2 id="🏛️-capitulo-i-el-protocolo-ipv4" tabindex="-1">🏛️ CAPÍTULO I: El Protocolo IPv4 <a class="header-anchor" href="#🏛️-capitulo-i-el-protocolo-ipv4" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Protocolo IPv4&quot;">​</a></h2><p>Una dirección IPv4 es simplemente un número binario larguísimo de 32 ceros y unos. Como los humanos somos malos leyendo 32 bits seguidos (<code>11000000101010000000000100001010</code>), lo dividimos en 4 bloques de 8 bits (Octetos) y los convertimos a números decimales separados por puntos. Ejemplo: <code>192.168.1.10</code>.</p><h3 id="_1-1-red-vs-host-calle-vs-casa" tabindex="-1">1.1 Red vs Host (Calle vs Casa) <a class="header-anchor" href="#_1-1-red-vs-host-calle-vs-casa" aria-label="Permalink to &quot;1.1 Red vs Host (Calle vs Casa)&quot;">​</a></h3><p>Toda dirección IP está dividida lógicamente en dos porciones:</p><ul><li><strong>Porción de Red (Net ID):</strong> Representa la calle o el barrio. Todas las computadoras conectadas al mismo switch o router <em>deben</em> tener la misma Porción de Red para poder hablar entre sí.</li><li><strong>Porción de Host:</strong> Representa el número de tu casa. Es el identificador único de tu máquina dentro de esa calle.</li></ul><p>¿Cómo sabe la computadora dónde termina la calle y dónde empieza el número de la casa? Gracias a la <strong>Máscara de Subred (Subnet Mask)</strong>. Si la máscara es <code>255.255.255.0</code>, los &quot;255&quot; indican la calle (<code>192.168.1</code>) y el &quot;0&quot; indica la casa (<code>.10</code>).</p><hr><h2 id="🧩-capitulo-ii-subnetting-el-arte-de-dividir-redes" tabindex="-1">🧩 CAPÍTULO II: Subnetting (El Arte de Dividir Redes) <a class="header-anchor" href="#🧩-capitulo-ii-subnetting-el-arte-de-dividir-redes" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Subnetting (El Arte de Dividir Redes)&quot;">​</a></h2><p>Imagina que una empresa te da la red <code>192.168.1.0</code> (que soporta 254 computadoras). Pero la empresa tiene 4 departamentos: Ventas, RRHH, Sistemas y Finanzas. Por seguridad, Ventas no debe poder ver las computadoras de RRHH. Si conectas a los 254 en el mismo switch, todos se verán.</p><p><strong>Subnetting</strong> es una operación matemática a nivel binario donde &quot;robamos&quot; bits de la Porción de Host y se los regalamos a la Porción de Red. Al hacer esto, tomamos una calle gigante de 254 casas y la partimos en 4 calles pequeñas de 62 casas, separadas lógicamente con barreras impenetrables (a menos que uses un Router).</p><p><em>Ventajas del Subnetting:</em></p><ol><li><strong>Seguridad:</strong> Aísla departamentos.</li><li><strong>Rendimiento:</strong> Reduce el ruido de &quot;Broadcast&quot; (si alguien grita en Ventas, RRHH ya no lo escucha).</li><li><strong>Organización Administrativa.</strong></li></ol><hr><h2 id="🏗️-capitulo-iii-el-enrutamiento-routing" tabindex="-1">🏗️ CAPÍTULO III: El Enrutamiento (Routing) <a class="header-anchor" href="#🏗️-capitulo-iii-el-enrutamiento-routing" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: El Enrutamiento (Routing)&quot;">​</a></h2><p>Una vez que dividiste la empresa en 4 subredes, estas subredes están aisladas. ¿Cómo hacemos si un usuario de Ventas <em>necesita legítimamente</em> enviarle un archivo al Servidor de Sistemas? Necesitamos un <strong>Router</strong> (Enrutador).</p><p>El Router es un dispositivo que tiene una &quot;pierna&quot; (cable) en la red de Ventas y otra en la de Sistemas. Su trabajo es recibir un paquete, consultar un mapa interno llamado <strong>Tabla de Enrutamiento</strong>, y decidir por cuál puerto debe reenviar el paquete.</p><h3 id="_3-1-tipos-de-enrutamiento" tabindex="-1">3.1 Tipos de Enrutamiento <a class="header-anchor" href="#_3-1-tipos-de-enrutamiento" aria-label="Permalink to &quot;3.1 Tipos de Enrutamiento&quot;">​</a></h3><ul><li><strong>Estático:</strong> El administrador entra a la consola del Router y escribe manualmente el mapa de rutas. <em>&quot;Si buscas la red de Sistemas, sal por el puerto 2&quot;</em>. Es seguro, pero inmanejable en el internet global donde hay millones de rutas.</li><li><strong>Dinámico:</strong> Los routers utilizan protocolos de inteligencia artificial (como OSPF o BGP). Los routers hablan entre sí automáticamente: <em>&quot;Hola, yo conozco el camino a la Universidad, y estoy a 2 milisegundos de distancia&quot;</em>. Si un cable submarino se rompe en el océano, el protocolo dinámico recalcula matemáticamente una nueva ruta por otro país en segundos.</li></ul><hr><h2 id="💻-el-salto-a-ipv6" tabindex="-1">💻 El Salto a IPv6 <a class="header-anchor" href="#💻-el-salto-a-ipv6" aria-label="Permalink to &quot;💻 El Salto a IPv6&quot;">​</a></h2><p>IPv4 se inventó en los 80s y solo permitía 4.300 millones de direcciones IP. Con la llegada de los smartphones y el &quot;Internet de las Cosas&quot; (neveras y focos con WiFi), ¡Nos quedamos sin direcciones IP en el mundo real!</p><p>Para salvar el internet, se inventó <strong>IPv6</strong>. IPv6 usa direcciones de 128 bits expresadas en formato hexadecimal gigante. (Ej: <code>2001:0db8:85a3:0000:0000:8a2e:0370:7334</code>). La cantidad de IPs posibles con IPv6 es tan monstruosa que podríamos asignarle una dirección IP única a cada grano de arena del planeta Tierra y aún sobrarían billones.</p><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Dirección IPv4:</strong> Identificador lógico numérico de 32 bits segmentado en cuatro octetos decimales, empleado en la Capa 3 del modelo OSI para el enrutamiento unicast, multicast y broadcast en redes TCP/IP.</li><li><strong>Máscara de Subred (Subnet Mask):</strong> Máscara de bits de 32 posiciones utilizada mediante operaciones lógicas AND en conjunto con una IP para segmentar matemáticamente e identificar la frontera exacta entre la Porción de Red y la Porción de Host.</li><li><strong>Subnetting (Subneteo):</strong> Técnica de ingeniería de diseño de redes que particiona algorítmicamente un espacio de direccionamiento IP mayor en múltiples subredes lógicas independientes, optimizando el rendimiento mediante la reducción de dominios de broadcast.</li><li><strong>Enrutamiento Estático:</strong> Configuración manual de métricas y trayectorias en la tabla de ruteo de un dispositivo de Capa 3, caracterizado por su rigidez ante cambios topológicos y nulo consumo de procesamiento dinámico.</li><li><strong>Protocolos de Enrutamiento Dinámico:</strong> Algoritmos distribuidos (como OSPF o BGP) que permiten a los enrutadores intercambiar automáticamente topologías de red y calcular rutas métricas óptimas en tiempo real frente a fluctuaciones en la infraestructura.</li><li><strong>IPv6:</strong> Actualización estructural del protocolo de internet (Capa 3) que amplía el espacio de direccionamiento a 128 bits en nomenclatura hexadecimal, integrando de forma nativa soporte para IPsec y eliminando la necesidad de NAT (Network Address Translation).</li></ul>',33)])])}const g=a(n,[["render",r]]);export{p as __pageData,g as default};
